$adminUrl=is_callable($adminUrl??null)?$adminUrl:static fn(string $path=''):string=>'/'.trim($path,'/');$workspace=is_array($workspace??null)?$workspace:[];$items=$workspace['items']??[];$filters=is_array($filters??null)?$filters:[];$noticeMessages=['created'=>'Form created successfully.','updated'=>'Form updated successfully.','published'=>'Form published successfully.','disabled'=>'Form disabled successfully.','deleted'=>'Form deleted successfully.'];$notice=is_scalar($notice??null)?($noticeMessages[(string)$notice]??null):null;$error=is_scalar($error??null)?(string)$error:'';$page=(int)($filters['page']??1);$perPage=(int)($filters['per_page']??25);$total=(int)($workspace['total']??0);$pages=max(1,(int)ceil($total/max(1,$perPage)));$query=static function(int $target)use($filters):string{$parameters=array_filter(['q'=>$filters['q']??null,'status'=>$filters['status']??null,'per_page'=>$filters['per_page']??null,'page'=>$target],static fn($value)=>$value!==null&&$value!=='');return http_build_query($parameters);};
